+struct MaskCastTopKParams {
+  const int32_t* __restrict__ in_topk_ids;
+  int64_t* __restrict__ out_topk_ids;
+  const int32_t* __restrict__ ntn_ptr;
+  int32_t ntn_value;
+  int64_t in_stride;
+  int64_t out_stride;
+  uint32_t topk;
