+        .with_dtype<uint8_t>()
+        .with_device<kDLCUDA>(device)
+        .ensure_alignment(N % kElemPerThread == 0 ? 8 : 1)
+        .verify(output);
+    TensorMatcher({N_padded / 64, M})
+        .with_dtype<uint16_t>()
+        .with_device<kDLCUDA>(device)
+        .ensure_alignment(2)
+        .verify(output_scale);
